seq_lines = []
with open("region.fasta") as f:
    f.readline()
    for line in f:
        seq_lines.append(line.strip())
seq = "".join(seq_lines).upper()

def revcomp(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

stops = {"TAA","TAG","TGA"}

def sixframe(s):
    out=[]
    for strand, ss in (("+", s), ("-", revcomp(s))):
        for frame in range(3):
            i=frame
            while i+2 < len(ss):
                codon = ss[i:i+3]
                if codon in stops:
                    i += 3
                    continue
                # start ORF scan
                j=i
                orfs=[]
                while j+2 < len(ss):
                    if ss[j:j+3] in stops:
                        out.append((strand, frame, i, j, ss[i:j+3]))
                        j+=3
                        break
                    j+=3
                else:
                    out.append((strand, frame, i, len(ss)-((len(ss)-i)%3), ss[i:]))
                    break
                i=j
    return out

# find ORFs >=150 aa between stops, requiring valid start codon scan (report longest between stop pairs)
def orfs_between_stops(s, minlen=120):
    res=[]
    for strand, ss in (("+", s), ("-", revcomp(s))):
        for frame in range(3):
            pos=frame
            seg_start=frame
            stop_pos=[]
            while pos+2 < len(ss):
                if ss[pos:pos+3] in stops:
                    stop_pos.append(pos)
                pos+=3
            prev = -3
            for sp in stop_pos:
                orf_len = sp - prev - 3  # codons between prev stop and this stop
                start_off = prev+3
                if orf_len >= minlen:
                    nt = ss[start_off:sp]
                    res.append((strand, frame, start_off, sp-3+3, orf_len//3, nt))
                prev = sp
            # trailing partial ORF
            if len(ss) - (prev+3) >= minlen*3:
                nt = ss[prev+3:]
                if not any(c in stops for c in [nt[i:i+3] for i in range(0,len(nt)-3,3)]):
                    res.append((strand, frame, prev+3, len(ss), len(nt)//3, nt))
    return res

res = orfs_between_stops(seq, minlen=100)
res.sort(key=lambda r: -r[4])
print("Longest ORFs between stops (min 100 aa):")
for r in res[:20]:
    strand, frame, a, b, aa, nt = r
    starts = [i for i in range(0,len(nt)-3,3) if nt[i:i+3] in ("ATG","GTG","TTG")]
    print(f"  strand {strand} frame {frame} len {aa} aa  (nt span {a}-{b} {'rev' if strand=='-' else ''}) "
          f"starts:{starts[:6]}")
